async function archiveAccount(formData: FormData) {
    "use server"
    const result = await archiveChartAccountAction({
      accountId: String(formData.get("accountId") || ""),
    })

    redirect(resultPath(locale, result.success, result.success ? "Account archived" : result.error))
  }

async function createEntry(formData: FormData) {
    "use server"
    const lines = [0, 1, 2, 3, 4, 5]
      .map((index) => ({
        accountId: String(formData.get(`accountId-${index}`) || ""),
        description: String(formData.get(`description-${index}`) || ""),
        debit: String(formData.get(`debit-${index}`) || ""),
        credit: String(formData.get(`credit-${index}`) || ""),
        currency: String(formData.get("currency") || "XAF"),
      }))
      .filter((line) => line.accountId && (line.debit || line.credit))

    const result = await createManualJournalEntryAction({
      journalId: String(formData.get("journalId") || ""),
      entryDate: String(formData.get("entryDate") || ""),
      memo: String(formData.get("memo") || ""),
      reference: String(formData.get("reference") || ""),
      lines,
    })

    if (result.success) return { success: true as const }
    return { success: false as const, error: result.error, code: result.code, reason: getModuleOperationErrorReason(result) }
  }

async function saveSettings(formData: FormData) {
    "use server"
    const result = await updateAccountingSettingsAction({
      countryPack: String(formData.get("countryPack") || "OHADA"),
      baseCurrency: String(formData.get("baseCurrency") || "XAF"),
      fiscalYearStartMonth: Number(formData.get("fiscalYearStartMonth") || 1),
      fiscalYearStartDay: Number(formData.get("fiscalYearStartDay") || 1),
      setupStatus: "IN_PROGRESS",
    })

    redirect(resultPath(locale, result.success, result.success ? "Accounting settings saved" : result.error))
  }

async function ensureJournals() {
    "use server"
    const result = await ensureDefaultJournalsAction({})
    redirect(resultPath(locale, result.success, result.success ? "Default journals ensured" : result.error))
  }

async function createFiscalYear(formData: FormData) {
    "use server"
    const result = await createFiscalYearAction({
      name: String(formData.get("name") || ""),
      startDate: String(formData.get("startDate") || ""),
      endDate: String(formData.get("endDate") || ""),
      createMonthlyPeriods: true,
    })

    redirect(resultPath(locale, result.success, result.success ? "Fiscal year created" : result.error))
  }

async function closePeriod(formData: FormData) {
    "use server"
    const result = await closeAccountingPeriodAction({
      periodId: String(formData.get("periodId") || ""),
      expectedVersion: Number(formData.get("expectedVersion") ?? NaN),
    })

    redirect(resultPath(locale, result.success, result.success ? (locale === "fr" ? "Période comptable clôturée" : "Accounting period closed") : result.error))
  }

async function markReady() {
    "use server"
    const result = await markAccountingSetupReadyAction({})
    redirect(resultPath(locale, result.success, result.success ? "Accounting setup marked ready" : result.error))
  }

async function handleCreateItem(formData: FormData) {
  "use server"

  await checkPermission("inventory.items.create")

  const user = await getAuthenticatedUser()
  if (!user?.organizationId) {
    return {
      success: false,
      error: "Organization not found",
    }
  }

  const text = (key: string) => String(formData.get(key) ?? "").trim()
  const optionalText = (key: string) => {
    const value = text(key)
    return value.length > 0 ? value : null
  }

  const parseNumber = (
    key: string,
    options: {
      required?: boolean
      fallback?: number | null
      min?: number
      max?: number
    } = {},
  ) => {
    const value = text(key)

    if (!value) {
      return options.required ? Number.NaN : (options.fallback ?? null)
    }

    const parsed = Number(value)
    if (!Number.isFinite(parsed)) {
      return Number.NaN
    }

    if (typeof options.min === "number" && parsed < options.min) {
      return Number.NaN
    }

    if (typeof options.max === "number" && parsed > options.max) {
      return Number.NaN
    }

    return parsed
  }

  const toBoolean = (key: string, fallback: boolean) => {
    const raw = formData.get(key)
    if (raw === null) return fallback
    if (typeof raw !== "string") return fallback

    const normalized = raw.trim().toLowerCase()
    if (["true", "1", "on", "yes"].includes(normalized)) {
      return true
    }
    if (["false", "0", "off", "no"].includes(normalized)) {
      return false
    }

    return fallback
  }

  const openingQuantity = parseNumber("initialInventory.quantity", { fallback: 0, min: 0 })
  const openingLocationId = optionalText("initialInventory.locationId")
  const initialInventory = typeof openingQuantity === "number" && openingQuantity > 0
    ? {
        locationId: openingLocationId ?? "",
        quantity: openingQuantity,
        unitCost: parseNumber("initialInventory.unitCost", { fallback: 0, min: 0 }) ?? 0,
        notes: optionalText("initialInventory.notes") ?? undefined,
        referenceNumber: optionalText("initialInventory.referenceNumber") ?? undefined,
      }
    : undefined

  const data = {
    nameEn: text("nameEn"),
    nameFr: optionalText("nameFr"),
    descriptionEn: optionalText("descriptionEn"),
    descriptionFr: optionalText("descriptionFr"),
    sku: optionalText("sku") || generateSimpleSKU(9, "ITEM"),
    costPrice: parseNumber("costPrice", { required: true, fallback: 0, min: 0 }),
    sellingPrice: parseNumber("sellingPrice", { required: true, fallback: 0, min: 0 }),
    tax: parseNumber("tax", { min: 0, max: 1000 }),
    thumbnail: optionalText("thumbnail"),
    imageUrls: optionalText("imageUrls"),
    organizationId: user.organizationId,
    categoryId: optionalText("categoryId"),
    brandId: optionalText("brandId"),
    unitId: optionalText("unitId"),
    taxRateId: optionalText("taxRateId"),
    barcode: optionalText("barcode"),
    weight: parseNumber("weight", { min: 0 }),
    dimensions: optionalText("dimensions"),
    minStockLevel: parseNumber("minStockLevel", { required: true, fallback: 0, min: 0 }),
    maxStockLevel: parseNumber("maxStockLevel", { fallback: null, min: 0 }),
    unitOfMeasure: optionalText("unitOfMeasure"),
    isActive: toBoolean("isActive", true),
    isSerialTracked: toBoolean("isSerialTracked", false),
    slug: optionalText("slug"),
    initialInventory,
  }

  const result = await createItemAction(data)

  if (!result.success) {
    return {
      success: false,
      error: result.error,
    }
  }

  const locale = pickLocale(await getLocale())
  const destination = `/${locale}/dashboard/inventory/items`
  revalidatePath(destination)

  return {
    success: true,
    redirect: destination,
  }
}

export default async function InventoryRoutePage(props: any = {}) {
  const surface = routeByKey("inventory-items")

  if (!surface) {
    throw new Error("Missing inventory route surface definition: inventory-items")
  }

  return withInventorySurfaceAccess({
    params: (props as { params?: Promise<{ locale: string }> }).params ?? Promise.resolve({ locale: "en" }),
    surface,
    onAllowed: async () => ItemsPageImpl(props),
  })
}

export default async function ItemsPage({
  params,
}: {
  params: Promise<{ locale: string }>
}) {
  const surface = routeByKey("items-dashboard")

  if (!surface) {
    throw new Error("Missing items route surface definition: items-dashboard")
  }

  return withItemsSurfaceAccess({
    params,
    surface,
    onAllowed: async () => {
      const locale = pickLocale((await params).locale)
      const t = await getTranslations()
      const user = await getAuthenticatedUser()
      const userOrg = user?.organizationId

      if (!userOrg) {
        return (
          <div className="container py-8">
            <div className="text-sm text-muted-foreground">{t("purchaseOrders.orgRequired.subtitle")}</div>
          </div>
        )
      }

      const [itemsRes, brandsRes, unitsRes, taxRatesRes, catsRes] = await Promise.all([
        getBriefOrgItems(userOrg).catch(() => null),
        getOrgBrands(userOrg).catch(() => null),
        getOrgUnits(userOrg).catch(() => null),
        getOrgTaxRates(userOrg).catch(() => null),
        getOrgCategories(userOrg).catch(() => null),
      ])

      const initialItemData = (itemsRes as { data?: unknown[] } | null)?.data ?? []
      const initialCategoryData = catsRes?.success ? (catsRes.data ?? []) : []
      const initialBrandData = brandsRes?.success ? (brandsRes.data ?? []) : []
      const initialUnitData = unitsRes?.success ? (unitsRes.data ?? []) : []
      const initialTaxRateData = taxRatesRes?.success ? (taxRatesRes.data ?? []) : []

      return (
        <div className="container py-8">
          <Suspense fallback={<TableLoading title={t("items.loadingItems")} />}>
            <ItemManagement
              title={t("nav.items")}
              editingId=""
              organizationId={userOrg}
              initialItemData={initialItemData as never}
              initialCategoryData={initialCategoryData as never}
              initialBrandData={initialBrandData as never}
              initialUnitData={initialUnitData as never}
              initialTaxRateData={initialTaxRateData as never}
              locale={locale}
            />
          </Suspense>
        </div>
      )
    },
  })
}

async function handleCreatePurchaseOrder(formData: FormData) {
  "use server"

  const user = await getAuthenticatedUser()
  if (!user?.organizationId) {
    throw new Error("Organization ID is required")
  }

  const result = await createPurchaseOrder({
    organizationId: user.organizationId,
    requestId: String(formData.get("requestId") || "") || undefined,
    supplierId: String(formData.get("supplierId") ?? ""),
    locationId: String(formData.get("locationId") ?? ""),
    date: String(formData.get("date") ?? ""),
    expectedDeliveryDate: String(formData.get("expectedDeliveryDate") ?? ""),
    paymentTerms: String(formData.get("paymentTerms") || "Net 30 days"),
    notes: String(formData.get("notes") || ""),
    shippingCost: Number.parseFloat(String(formData.get("shippingCost") || "0")) || 0,
    orderLines: JSON.parse(String(formData.get("orderLines") || "[]")),
  })

  if (!result.success) {
    if (getModuleOperationErrorReason(result)) return { success: false as const, error: result.error || "New work is stopped", code: result.code, reason: result.reason }
    throw new Error(result.error || "Failed to create purchase order")
  }

  await localizedRedirect("/dashboard/purchase-orders")
}
